import sys
import math
import bisect

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    q = data[0]
    queries = data[1:1 + q]
    max_a = max(queries)
    max_m = math.isqrt(max_a)

    # omega[x] = number of distinct prime factors of x
    omega = [0] * (max_m + 1)
    for i in range(2, max_m + 1):
        if omega[i] == 0:
            for j in range(i, max_m + 1, i):
                omega[j] += 1

    # A 400 number is m^2 where m has exactly 2 distinct prime factors.
    nums = []
    for m in range(2, max_m + 1):
        if omega[m] == 2:
            nums.append(m * m)

    out = []
    for a in queries:
        idx = bisect.bisect_right(nums, a) - 1
        out.append(str(nums[idx]))

    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    main()

import sys

def solve():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    it = iter(data)
    T = int(next(it))
    out_lines = []
    for _ in range(T):
        N = int(next(it))
        K = int(next(it))
        M = 2 * K
        items = []
        for i in range(N):
            x = int(next(it)); y = int(next(it)); z = int(next(it))
            max_val = x if x >= y and x >= z else (y if y >= z else z)
            if x == max_val:
                c = 0
            elif y == max_val:
                c = 1
            else:
                c = 2
            items.append((max_val, x, y, z, c, i))
        items.sort(key=lambda v: v[0], reverse=True)
        selected = items[:M]
        unselected = items[M:]
        sum_max = sum(v[0] for v in selected)
        counts = [0, 0, 0]
        for v in selected:
            counts[v[4]] += 1

        if counts[0] % 2 == 0 and counts[1] % 2 == 0 and counts[2] % 2 == 0:
            out_lines.append(str(sum_max))
            continue

        # best_flip[c][d] = list of (cost, id)
        best_flip = [[[] for _ in range(3)] for __ in range(3)]
        for v in selected:
            max_v, x, y, z, c, idx = v
            for d in range(3):
                if d == c:
                    continue
                if d == 0:
                    val = x
                elif d == 1:
                    val = y
                else:
                    val = z
                cost = max_v - val
                lst = best_flip[c][d]
                lst.append((cost, idx))
                lst.sort(key=lambda t: t[0])
                if len(lst) > 2:
                    lst.pop()

        # smallest_sel[c] = list of (max, id)
        smallest_sel = [[] for _ in range(3)]
        for v in selected:
            max_v, x, y, z, c, idx = v
            lst = smallest_sel[c]
            lst.append((max_v, idx))
            lst.sort(key=lambda t: t[0])
            if len(lst) > 2:
                lst.pop()

        # best_unsel[d] = list of (val, id)
        best_unsel = [[] for _ in range(3)]
        for v in unselected:
            max_v, x, y, z, c, idx = v
            for d in range(3):
                if d == 0:
                    val = x
                elif d == 1:
                    val = y
                else:
                    val = z
                lst = best_unsel[d]
                lst.append((val, idx))
                lst.sort(key=lambda t: -t[0])
                if len(lst) > 2:
                    lst.pop()

        ops = []
        # flips
        for c in range(3):
            for d in range(3):
                if c == d:
                    continue
                for cost, idx in best_flip[c][d]:
                    delta = [0, 0, 0]
                    delta[c] -= 1
                    delta[d] += 1
                    ops.append((cost, tuple(delta), frozenset([idx])))
        # swaps
        for c in range(3):
            for d in range(3):
                if c == d:
                    continue
                for max_sel, sel_id in smallest_sel[c]:
                    for val_unsel, unsel_id in best_unsel[d]:
                        cost = max_sel - val_unsel
                        delta = [0, 0, 0]
                        delta[c] -= 1
                        delta[d] += 1
                        ops.append((cost, tuple(delta), frozenset([sel_id, unsel_id])))

        INF = 10**18
        min_loss = INF
        num_ops = len(ops)
        # single operation
        for i in range(num_ops):
            cost, delta, used = ops[i]
            nc = [counts[0] + delta[0], counts[1] + delta[1], counts[2] + delta[2]]
            if nc[0] % 2 == 0 and nc[1] % 2 == 0 and nc[2] % 2 == 0:
                if cost < min_loss:
                    min_loss = cost
        # pairs of operations
        for i in range(num_ops):
            cost1, delta1, used1 = ops[i]
            for j in range(i + 1, num_ops):
                cost2, delta2, used2 = ops[j]
                if used1.isdisjoint(used2):
                    nc = [counts[0] + delta1[0] + delta2[0],
                          counts[1] + delta1[1] + delta2[1],
                          counts[2] + delta1[2] + delta2[2]]
                    if nc[0] % 2 == 0 and nc[1] % 2 == 0 and nc[2] % 2 == 0:
                        total = cost1 + cost2
                        if total < min_loss:
                            min_loss = total
        out_lines.append(str(sum_max - min_loss))
    sys.stdout.write("\n".join(out_lines))

