import sys

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    N, K = data[0], data[1]
    A = data[2:2 + N]

    # binomial coefficients up to K
    comb = [0] * (K + 1)
    comb[0] = 1
    for n in range(1, K + 1):
        for r in range(n, 0, -1):
            comb[r] = (comb[r] + comb[r - 1]) % MOD

    # prev[s] = sum of P[i]^s over already processed prefixes P[i]
    prev = [0] * (K + 1)
    prev[0] = 1  # P[0] = 0, 0^0 = 1

    ans = 0
    pref = 0

    for a in A:
        pref = (pref + a) % MOD

        powers = [1] * (K + 1)
        for e in range(1, K + 1):
            powers[e] = powers[e - 1] * pref % MOD

        for s in range(K + 1):
            term = comb[s] * prev[s] % MOD * powers[K - s] % MOD
            if s & 1:
                ans -= term
            else:
                ans += term

        ans %= MOD

        for e in range(K + 1):
            prev[e] = (prev[e] + powers[e]) % MOD

    print(ans % MOD)

if __name__ == "__main__":
    main()

import sys

def solve() -> None:
    data = sys.stdin.read().split()
    if not data:
        return
    T = int(data[0])
    idx = 1
    out = []
    OFFSET = 1000000

    def gen_axis_cycle(L: int):
        res = []
        if L == 2:
            res.append((0, 0))
            res.append((1, 0))
        else:
            a = L // 2 - 1
            for i in range(a + 1):
                res.append((i, 0))
            res.append((a, 1))
            for i in range(a - 1, -1, -1):
                res.append((i, 1))
        return res

    for _ in range(T):
        R = int(data[idx]); B = int(data[idx + 1]); idx += 2

        # Necessary and sufficient condition
        if R % 2 != 0 or (R == 0 and B % 2 != 0):
            out.append("No")
            continue

        out.append("Yes")

        if R == 0:
            # All blue: use diagonal cycle
            L = B
            axis = gen_axis_cycle(L)
            res = [(x + y, x - y) for (x, y) in axis]
            for r, c in res:
                out.append(f"B {r + OFFSET} {c + OFFSET}")

        elif B == 0:
            # All red: use axis cycle
            L = R
            res = gen_axis_cycle(L)
            for r, c in res:
                out.append(f"R {r + OFFSET} {c + OFFSET}")

        else:
            # Mixed colors
            res = []
            if B % 2 == 1:
                k = (R - 2) // 2
                m = (B - 1) // 2
                res.append((0, 0))
                res.append((1, 0))
                # E2': from (1,0) to (1,1)
                if m == 0:
                    res.append((1, 1))
                else:
                    for i in range(1, m + 1):
                        res.append((1 + i, i))
                    res.append((1 + m, m + 1))
                    for i in range(1, m + 1):
                        res.append((1 + m - i, m + 1 - i))
                # E3': from (1,1) to (0,0)
                if k > 0:
                    for i in range(1, k + 1):
                        res.append((1 - i, 1))
                    res.append((-k, 0))
                    for i in range(1, k):
                        res.append((-k + i, 0))
            else:
                k = R // 2
                m = B // 2
                kp = k - 1
                mp = m - 1
                res.append((0, 0))
                res.append((1, 0))
                # E2': from (1,0) to (2,1)
                if kp == 0:
                    res.append((2, 1))
                else:
                    for i in range(1, kp + 1):
                        res.append((1 + i, 0))
                    res.append((2 + kp, 1))
                    for i in range(1, kp + 1):
                        res.append((2 + kp - i, 1))
                # E3': from (2,1) to (1,1)
                if mp == 0:
                    res.append((1, 1))
                else:
                    for i in range(1, mp + 1):
                        res.append((2 + i, 1 + i))
                    res.append((1 + mp, 1 + mp))
                    for i in range(1, mp + 1):
                        res.append((1 + mp - i, 1 + mp - i))

            N = len(res)
            for i in range(N):
                j = (i + 1) % N
                dr = res[j][0] - res[i][0]
                dc = res[j][1] - res[i][1]
                if abs(dr) + abs(dc) == 1:
                    p = 'R'
                else:
                    p = 'B'
                r, c = res[i]
                out.append(f"{p} {r + OFFSET} {c + OFFSET}")

    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    solve()

