import sys

def solve() -> None:
    input = sys.stdin.readline
    N, M = map(int, input().split())
    adj = [[] for _ in range(N + 1)]
    for _ in range(M):
        u, v = map(int, input().split())
        adj[u].append(v)
        adj[v].append(u)

    # If N is odd, the final complete bipartite graph always has an even number of edges.
    if N % 2 == 1:
        print("Aoki" if M % 2 == 1 else "Takahashi")
        return

    visited = [False] * (N + 1)
    color = [-1] * (N + 1)

    o = 0          # number of components with odd size
    e = 0          # number of components with even size
    A_even = 0     # sum of (size of one bipartition side) mod 2 over even components, mod 2

    for i in range(1, N + 1):
        if not visited[i]:
            stack = [i]
            visited[i] = True
            color[i] = 0
            cnt = [0, 0]
            while stack:
                u = stack.pop()
                cnt[color[u]] += 1
                for v in adj[u]:
                    if not visited[v]:
                        visited[v] = True
                        color[v] = color[u] ^ 1
                        stack.append(v)

            s = cnt[0] + cnt[1]
            if s % 2 == 1:
                o += 1
            else:
                e += 1
                A_even = (A_even + cnt[0]) % 2

    P_mod2 = (M + A_even) % 2

    if o == 0:
        if P_mod2 == 1:
            print("Aoki")
        else:
            print("Takahashi")
    elif o == 2:
        print("Aoki")
    else:  # o >= 4
        if (e + P_mod2) % 2 == 1:
            print("Aoki")
        else:
            print("Takahashi")


if __name__ == "__main__":
    solve()

class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        from functools import lru_cache

        def count_upto(x: int) -> int:
            if x <= 0:
                return 0

            digits = str(x)
            n = len(digits)

            @lru_cache(maxsize=None)
            def dp(pos: int, digit_sum: int, digit_prod: int, tight: bool, started: bool) -> int:
                if pos == n:
                    return 1 if started and digit_prod % digit_sum == 0 else 0

                limit = int(digits[pos]) if tight else 9
                total = 0

                for d in range(limit + 1):
                    next_tight = tight and (d == limit)

                    if not started and d == 0:
                        total += dp(pos + 1, 0, 1, next_tight, False)
                    else:
                        total += dp(pos + 1, digit_sum + d, digit_prod * d, next_tight, True)

                return total

            return dp(0, 0, 1, True, False)

        return count_upto(r) - count_upto(l - 1)

from typing import List

class Solution:
    def longestCommonPrefix(self, words: List[str], k: int) -> List[int]:
        n = len(words)

        # Trie arrays
        children = [{}]
        depth = [0]
        cnt = [0]
        term = [[]]

        for i, s in enumerate(words):
            node = 0
            for ch in s:
                d = children[node]
                nxt = d.get(ch)
                if nxt is None:
                    nxt = len(children)
                    d[ch] = nxt
                    children.append({})
                    depth.append(depth[node] + 1)
                    cnt.append(0)
                    term.append([])
                node = nxt
                cnt[node] += 1
            term[node].append(i)

        cnt[0] = n
        m = len(children)

        tin = [0] * m
        tout = [0] * m
        pos = [0] * n
        cur = 0

        # DFS order over word occurrences
        stack = [(0, 0)]
        while stack:
            v, state = stack.pop()
            if state == 0:
                tin[v] = cur + 1
                for idx in term[v]:
                    cur += 1
                    pos[idx] = cur
                stack.append((v, 1))
                for child in children[v].values():
                    stack.append((child, 0))
            else:
                tout[v] = cur

        global_best = 0
        size = 1
        while size < n:
            size <<= 1

        tree = [0] * (2 * size)

        def update(l: int, r: int, val: int) -> None:
            if l > r:
                return
            l += size - 1
            r += size - 1
            while l <= r:
                if l & 1:
                    if val > tree[l]:
                        tree[l] = val
                    l += 1
                if not (r & 1):
                    if val > tree[r]:
                        tree[r] = val
                    r -= 1
                l >>= 1
                r >>= 1

        for v in range(m):
            c = cnt[v]
            if c >= k:
                d = depth[v]
                if c >= k + 1 and d > global_best:
                    global_best = d

                l = tin[v]
                r = tout[v]
                if l > 1:
                    update(1, l - 1, d)
                if r < n:
                    update(r + 1, n, d)

        ans = [0] * n
        for i in range(n):
            p = pos[i] - 1 + size
            best = 0
            while p >= 1:
                if tree[p] > best:
                    best = tree[p]
                p >>= 1
            if global_best > best:
                best = global_best
            ans[i] = best

        return ans

import sys
from collections import deque

sys.setrecursionlimit(1000000)

class Edge:
    __slots__ = ('to', 'rev', 'cap')
    def __init__(self, to, rev, cap):
        self.to = to
        self.rev = rev
        self.cap = cap

class Dinic:
    def __init__(self, n):
        self.n = n
        self.adj = [[] for _ in range(n)]

    def add_edge(self, u, v, cap):
        self.adj[u].append(Edge(v, len(self.adj[v]), cap))
        self.adj[v].append(Edge(u, len(self.adj[u]) - 1, 0))

    def max_flow(self, s, t, limit):
        flow = 0
        n = self.n
        while flow < limit:
            level = [-1] * n
            q = deque([s])
            level[s] = 0
            while q:
                v = q.popleft()
                for e in self.adj[v]:
                    if e.cap > 0 and level[e.to] < 0:
                        level[e.to] = level[v] + 1
                        q.append(e.to)
            if level[t] < 0:
                break
            it = [0] * n
            while flow < limit:
                f = self.dfs(s, t, limit - flow, level, it)
                if f == 0:
                    break
                flow += f
        return flow

    def dfs(self, v, t, f, level, it):
        if v == t:
            return f
        while it[v] < len(self.adj[v]):
            e = self.adj[v][it[v]]
            if e.cap > 0 and level[v] + 1 == level[e.to]:
                ret = self.dfs(e.to, t, min(f, e.cap), level, it)
                if ret > 0:
                    e.cap -= ret
                    self.adj[e.to][e.rev].cap += ret
                    return ret
            it[v] += 1
        return 0

def solve():
    data = list(map(int, sys.stdin.read().split()))
    if not data:
        return
    it = iter(data)
    N = next(it)
    M = next(it)
    K = next(it)
    edges = []
    for _ in range(M):
        u = next(it) - 1
        v = next(it) - 1
        edges.append((u, v))

    INF = 10**9
    ans = 0
    for D in range(1, N):
        nodes = N * D + 2
        S = N * D
        T = N * D + 1
        dinic = Dinic(nodes)

        def vid(v, i):
            return v * D + (i - 1)

        for v in range(N):
            for i in range(1, D):
                dinic.add_edge(vid(v, i + 1), vid(v, i), INF)

        for i in range(1, D + 1):
            dinic.add_edge(vid(0, i), T, INF)
            dinic.add_edge(S, vid(N - 1, i), INF)

        for u, v in edges:
            for i in range(1, D + 1):
                dinic.add_edge(vid(v, i), vid(u, i), 1)
            for i in range(1, D):
                dinic.add_edge(vid(v, i + 1), vid(u, i), INF)

        flow = dinic.max_flow(S, T, K + 1)
        if flow <= K:
            ans = D
        else:
            break

    print(ans)

