import sys

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    N = data[0]
    K = data[1]
    V = N * K

    if K == 1:
        print("Yes")
        return

    adj = [[] for _ in range(V + 1)]
    idx = 2
    for _ in range(V - 1):
        u = data[idx]
        v = data[idx + 1]
        idx += 2
        adj[u].append(v)
        adj[v].append(u)

    parent = [0] * (V + 1)
    parent[1] = -1
    order = [1]

    for v in order:
        for to in adj[v]:
            if to != parent[v]:
                parent[to] = v
                order.append(to)

    sz = [0] * (V + 1)
    open_state = [False] * (V + 1)
    closed_state = [False] * (V + 1)

    for v in reversed(order):
        total = 1
        m = 0
        r1 = r2 = 0
        fail = False

        for to in adj[v]:
            if parent[to] == v:
                total += sz[to]
                r = sz[to] % K
                if r != 0:
                    if not open_state[to]:
                        fail = True
                    m += 1
                    if m == 1:
                        r1 = r
                    elif m == 2:
                        r2 = r
                else:
                    if not closed_state[to]:
                        fail = True

        sz[v] = total

        if fail:
            continue

        if m == 0:
            open_state[v] = True
            closed_state[v] = False
        elif m == 1:
            open_state[v] = (1 + r1 < K)
            closed_state[v] = (1 + r1 == K)
        elif m == 2:
            open_state[v] = False
            closed_state[v] = (1 + r1 + r2 == K)
        else:
            open_state[v] = False
            closed_state[v] = False

    print("Yes" if closed_state[1] else "No")


