def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    it = iter(data)
    N = next(it)
    M = next(it)

    adj = [[] for _ in range(N + 1)]
    for _ in range(M):
        x = next(it)
        y = next(it)
        z = next(it)
        adj[x].append((y, z))
        if x != y:
            adj[y].append((x, z))

    D = [-1] * (N + 1)
    comp = [-1] * (N + 1)
    comp_t = []

    B = 31

    for s in range(1, N + 1):
        if D[s] != -1:
            continue

        cid = len(comp_t)
        D[s] = 0
        comp[s] = cid
        stack = [s]
        verts = []

        while stack:
            u = stack.pop()
            verts.append(u)
            du = D[u]

            for v, z in adj[u]:
                if D[v] == -1:
                    D[v] = du ^ z
                    comp[v] = cid
                    stack.append(v)
                else:
                    if (du ^ D[v]) != z:
                        print(-1)
                        return

        size = len(verts)
        cnt = [0] * B
        for u in verts:
            d = D[u]
            for b in range(B):
                if (d >> b) & 1:
                    cnt[b] += 1

        t = 0
        for b in range(B):
            if cnt[b] * 2 > size:
                t |= 1 << b
        comp_t.append(t)

    ans = []
    for i in range(1, N + 1):
        ans.append(str(D[i] ^ comp_t[comp[i]]))

    sys.stdout.write(" ".join(ans) + "\n")

