class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n = len(str1)
        m = len(str2)
        L = n + m - 1

        # KMP prefix function for str2
        pi = [0] * m
        for i in range(1, m):
            j = pi[i - 1]
            while j > 0 and str2[i] != str2[j]:
                j = pi[j - 1]
            if str2[i] == str2[j]:
                j += 1
            pi[i] = j

        # KMP transitions: trans[state][char] -> next state
        trans = [[0] * 26 for _ in range(m + 1)]
        for s in range(m):
            for c in range(26):
                ch = chr(97 + c)
                if ch == str2[s]:
                    trans[s][c] = s + 1
                else:
                    if s == 0:
                        trans[s][c] = 0
                    else:
                        trans[s][c] = trans[pi[s - 1]][c]
        for c in range(26):
            trans[m][c] = trans[pi[m - 1]][c]

        # reach[s] = bitmask of all states reachable from s by one character
        reach = [0] * (m + 1)
        for s in range(m + 1):
            mask = 0
            for c in range(26):
                mask |= 1 << trans[s][c]
            reach[s] = mask

        # Positions forced by 'T' constraints
        fixed = [-1] * L
        for i, ch in enumerate(str1):
            if ch == 'T':
                for j in range(m):
                    pos = i + j
                    c = ord(str2[j]) - 97
                    if fixed[pos] == -1:
                        fixed[pos] = c
                    elif fixed[pos] != c:
                        return ""

        # Positions where the KMP state must not be m (i.e. the window must not equal str2)
        forbid = [False] * L
        for i, ch in enumerate(str1):
            if ch == 'F':
                e = i + m - 1
                forbid[e] = True

        # dp[pos] is a bitmask of KMP states from which positions pos..L-1 can be completed
        all_mask = (1 << (m + 1)) - 1
        dp = [0] * (L + 1)
        dp[L] = all_mask

        for pos in range(L - 1, -1, -1):
            next_mask = dp[pos + 1]
            allowed = next_mask
            if forbid[pos]:
                allowed &= ~(1 << m)

            if fixed[pos] != -1:
                c = fixed[pos]
                new_mask = 0
                for s in range(m + 1):
                    ns = trans[s][c]
                    if (allowed >> ns) & 1:
                        new_mask |= 1 << s
                dp[pos] = new_mask
            else:
                new_mask = 0
                for s in range(m + 1):
                    if reach[s] & allowed:
                        new_mask |= 1 << s
                dp[pos] = new_mask

        if (dp[0] & 1) == 0:
            return ""

        # Greedily build the lexicographically smallest string
        res = []
        s = 0
        for pos in range(L):
            if fixed[pos] != -1:
                chars = (fixed[pos],)
            else:
                chars = range(26)

            chosen = -1
            for c in chars:
                ns = trans[s][c]
                if forbid[pos] and ns == m:
                    continue
                if (dp[pos + 1] >> ns) & 1:
                    chosen = c
                    s = ns
                    break

            if chosen == -1:
                return ""
            res.append(chr(97 + chosen))

        return ''.join(res)

from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        INF = 10**15 + 1

        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = min(INF, fact[i - 1] * i)

        used = [False] * (n + 1)
        rem_o = (n + 1) // 2
        rem_e = n // 2
        last = -1
        ans = []

        for pos in range(n):
            chosen = False

            for v in range(1, n + 1):
                if used[v]:
                    continue

                p = v & 1  # 1 for odd, 0 for even

                if last != -1 and p == last:
                    continue

                no, ne = rem_o, rem_e
                if p == 1:
                    no -= 1
                else:
                    ne -= 1

                rem_len = n - pos - 1
                cnt = 0

                if rem_len == 0:
                    cnt = 1
                else:
                    req = 1 - p

                    if req == 1:
                        if no == (rem_len + 1) // 2 and ne == rem_len // 2:
                            cnt = fact[no] * fact[ne]
                    else:
                        if ne == (rem_len + 1) // 2 and no == rem_len // 2:
                            cnt = fact[no] * fact[ne]

                    if cnt > INF:
                        cnt = INF

                if k > cnt:
                    k -= cnt
                else:
                    ans.append(v)
                    used[v] = True
                    rem_o, rem_e = no, ne
                    last = p
                    chosen = True
                    break

            if not chosen:
                return []

        return ans

