MOD = 998244353

def mul(state, M):
    r0, r1 = state
    m0, m1 = M
    nr0 = 0
    if r0 & 1:
        nr0 |= m0
    if r0 & 2:
        nr0 |= m1
    nr1 = 0
    if r1 & 1:
        nr1 |= m0
    if r1 & 2:
        nr1 |= m1
    return (nr0, nr1)

def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    N = int(data[0])
    s = data[1]  # bytes

    # Matrices representing allowed transitions for each (s, d)
    M_U = (2, 0)  # d=0
    M_I = (1, 2)  # identity
    M_H = (0, 1)  # d=2 for s=0, d=3 for s=1
    M_C = (3, 2)  # s=1, d=1
    M_F = (1, 3)  # s=1, d=2

    all_M = [M_U, M_I, M_H, M_C, M_F]
    start = M_I

    # Discover all reachable non-empty relation states
    states = [start]
    idx = {start: 0}
    queue = [start]
    while queue:
        st = queue.pop()
        for M in all_M:
            ns = mul(st, M)
            if ns != (0, 0) and ns not in idx:
                idx[ns] = len(states)
                states.append(ns)
                queue.append(ns)

    S = len(states)
    trans0 = [[] for _ in range(S)]
    trans1 = [[] for _ in range(S)]

    mats0 = [M_U, M_I, M_H]          # s=0: d=0,1,2
    mats1 = [M_U, M_C, M_F, M_H]     # s=1: d=0,1,2,3

    for i, st in enumerate(states):
        for M in mats0:
            ns = mul(st, M)
            if ns != (0, 0):
                trans0[i].append(idx[ns])
        for M in mats1:
            ns = mul(st, M)
            if ns != (0, 0):
                trans1[i].append(idx[ns])

    def valid(st):
        r0, r1 = st
        return (r0 & 1) or (r1 & 2)

    # Merge states with identical transition lists and same acceptance
    sig_to_new = {}
    old_to_new = [0] * S
    new_valid = []
    for i in range(S):
        sig = (tuple(trans0[i]), tuple(trans1[i]), valid(states[i]))
        if sig not in sig_to_new:
            sig_to_new[sig] = len(new_valid)
            new_valid.append(valid(states[i]))
        old_to_new[i] = sig_to_new[sig]

    new_S = len(new_valid)
    new_trans0 = [[] for _ in range(new_S)]
    new_trans1 = [[] for _ in range(new_S)]

    rep = [-1] * new_S
    for i in range(S):
        ni = old_to_new[i]
        if rep[ni] == -1:
            rep[ni] = i

    for ni in range(new_S):
        old = rep[ni]
        new_trans0[ni] = [old_to_new[x] for x in trans0[old]]
        new_trans1[ni] = [old_to_new[x] for x in trans1[old]]

    start_new = old_to_new[0]

    # Build edge lists for fast DP
    edges0 = []
    for curr in range(new_S):
        for nxt in new_trans0[curr]:
            edges0.append((curr, nxt))
    edges1 = []
    for curr in range(new_S):
        for nxt in new_trans1[curr]:
            edges1.append((curr, nxt))

    dp = [0] * new_S
    dp[start_new] = 1
    ndp = [0] * new_S

    for ch in s:
        for i in range(new_S):
            ndp[i] = 0
        if ch == 48:  # '0'
            for curr, nxt in edges0:
                ndp[nxt] += dp[curr]
        else:         # '1'
            for curr, nxt in edges1:
                ndp[nxt] += dp[curr]
        for i in range(new_S):
            ndp[i] %= MOD
        dp, ndp = ndp, dp

    ans = sum(dp[i] for i in range(new_S) if new_valid[i]) % MOD
    print(ans)

