from bisect import bisect_left

class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        S = side
        P = 4 * S

        # Map each boundary point to its position on the perimeter.
        arr = []
        for x, y in points:
            if y == 0:
                pos = x
            elif x == S:
                pos = S + y
            elif y == S:
                pos = 2 * S + (S - x)
            else:
                pos = 3 * S + (S - y)
            arr.append(pos)

        arr.sort()
        n = len(arr)

        def can(D: int) -> bool:
            if D <= 0:
                return True

            m = 2 * n
            pos = arr + [v + P for v in arr]

            # nxt[i] = first index j > i such that pos[j] - pos[i] >= D
            nxt = [m] * (m + 1)
            for i in range(m):
                target = pos[i] + D
                nxt[i] = bisect_left(pos, target, i + 1, m)

            LOG = (k + 1).bit_length()
            up = [nxt]
            for _ in range(1, LOG):
                prev = up[-1]
                curr = [m] * (m + 1)
                for i in range(m):
                    curr[i] = prev[prev[i]]
                up.append(curr)

            for i in range(n):
                limit = pos[i] + P - D
                cur = i
                cnt = 1
                if cnt >= k:
                    return True

                for j in range(LOG - 1, -1, -1):
                    nxt_node = up[j][cur]
                    if nxt_node < m and pos[nxt_node] <= limit:
                        cur = nxt_node
                        cnt += 1 << j
                        if cnt >= k:
                            return True

            return False

        lo, hi = 0, S
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if can(mid):
                lo = mid
            else:
                hi = mid - 1

        return lo

