class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        n = len(s)
        A, B, C = p.split('*')
        a, b, c = len(A), len(B), len(C)
        INF = 10**9

        def kmp(pat):
            m = len(pat)
            if m == 0 or m > n:
                return []

            pi = [0] * m
            j = 0
            for i in range(1, m):
                while j > 0 and pat[i] != pat[j]:
                    j = pi[j - 1]
                if pat[i] == pat[j]:
                    j += 1
                pi[i] = j

            res = []
            j = 0
            for i, ch in enumerate(s):
                while j > 0 and ch != pat[j]:
                    j = pi[j - 1]
                if ch == pat[j]:
                    j += 1
                if j == m:
                    res.append(i - m + 1)
                    j = pi[j - 1]

            return res

        # nextB[i] = smallest position >= i where B occurs
        if b > 0:
            occB = kmp(B)
            nextB = [INF] * (n + 2)
            isB = [False] * (n + 1)
            for m in occB:
                isB[m] = True
            for i in range(n, -1, -1):
                if isB[i]:
                    nextB[i] = i
                else:
                    nextB[i] = nextB[i + 1]
        else:
            nextB = [INF] * (n + 2)
            for i in range(n + 1):
                nextB[i] = i

        # nextC[i] = smallest end position >= i where C ends
        if c > 0:
            occC = kmp(C)
            nextC = [INF] * (n + 2)
            isEndC = [False] * (n + 1)
            for st in occC:
                isEndC[st + c] = True
            for i in range(n, -1, -1):
                if isEndC[i]:
                    nextC[i] = i
                else:
                    nextC[i] = nextC[i + 1]
        else:
            nextC = [INF] * (n + 2)
            for i in range(n + 1):
                nextC[i] = i

        ans = INF

        if a > 0:
            occA = kmp(A)
            for l in occA:
                L = l + a
                if L > n:
                    continue

                m = nextB[L]
                if m >= INF:
                    continue

                pos = m + b + c
                if pos > n:
                    continue

                r = nextC[pos]
                if r < INF:
                    ans = min(ans, r - l)
        else:
            for l in range(n + 1):
                m = nextB[l]
                if m >= INF:
                    continue

                pos = m + b + c
                if pos > n:
                    continue

                r = nextC[pos]
                if r < INF:
                    ans = min(ans, r - l)

        return -1 if ans == INF else ans

