class Solution:
    def countSubstrings(self, s: str) -> int:
        cnt = [None] * 10
        for d in range(1, 10):
            cnt[d] = [0] * d

        ans = 0

        for ch in s:
            x = ord(ch) - ord('0')

            for d in range(1, 10):
                old = cnt[d]
                new = [0] * d

                for v in range(d):
                    c = old[v]
                    if c:
                        new[(v * 10 + x) % d] += c

                new[x % d] += 1
                cnt[d] = new

            if x != 0:
