        dp = [0] * (N + 1)
        for i in range(N):
            dp[i + 1] = dp[i] + ((mask >> i) & 1)

        for c in range(26):
            ch = chr(c + ord('a'))
            ndp = [0] * (N + 1)

            for i in range(1, N + 1):
                best = dp[i]
                if ndp[i - 1] > best:
                    best = ndp[i - 1]
                if S[i - 1] == ch:
                    cand = dp[i - 1] + 1
                    if cand > best:
                        best = cand
                ndp[i] = best

            nmask = 0
            for i in range(N):
                if ndp[i + 1] > ndp[i]:
                    nmask |= 1 << i
            trans[mask][c] = nmask

    dp = [0] * states
    dp[0] = 1

    for _ in range(M):
        ndp = [0] * states
        for state, val in enumerate(dp):
            if val == 0:
