            row = trans[state]
            for c in range(26):
                ns = row[c]
                ndp[ns] += val
                if ndp[ns] >= MOD:
                    ndp[ns] -= MOD
        dp = ndp

    ans = [0] * (N + 1)
    for mask, val in enumerate(dp):
        k = mask.bit_count()
        ans[k] += val
        if ans[k] >= MOD:
            ans[k] -= MOD

    print(*ans)

