import sys
from collections import deque

def solve():
    input = sys.stdin.readline
    N, M, S, T = map(int, input().split())
    S -= 1
    T -= 1
    adj = [[] for _ in range(N)]
    edges = []
    for _ in range(M):
        u, v = map(int, input().split())
        u -= 1
        v -= 1
        adj[u].append(v)
        adj[v].append(u)
        edges.append((u, v))

    def bfs(s):
        dist = [-1] * N
        dist[s] = 0
        q = deque([s])
        while q:
            v = q.popleft()
            for u in adj[v]:
                if dist[u] == -1:
                    dist[u] = dist[v] + 1
                    q.append(u)
        return dist

    dS = bfs(S)
    dT = bfs(T)
    d = dS[T]

    # Find bridges using Tarjan's algorithm
    tin = [-1] * N
    low = [0] * N
    timer = 0
    is_bridge = set()
    sys.setrecursionlimit(300000)

    def dfs(v, p):
        nonlocal timer
        tin[v] = low[v] = timer
        timer += 1
        for u in adj[v]:
            if u == p:
                continue
            if tin[u] != -1:
                low[v] = min(low[v], tin[u])
            else:
                dfs(u, v)
                low[v] = min(low[v], low[u])
                if low[u] > tin[v]:
                    is_bridge.add((min(v, u), max(v, u)))

    for i in range(N):
        if tin[i] == -1:
            dfs(i, -1)

    # Check if S and T are in the same 2-edge-connected component
    vis = [False] * N
    q = deque([S])
    vis[S] = True
    while q:
        v = q.popleft()
        for u in adj[v]:
            if (min(v, u), max(v, u)) in is_bridge:
                continue
            if not vis[u]:
                vis[u] = True
                q.append(u)
    same_comp = vis[T]

    INF = 10**18
    ans = INF

    if same_comp:
        # There is a cycle containing S and T
        for u, v in edges:
            if (u == S and v == T) or (u == T and v == S):
                continue
            ans = min(ans, dS[u] + dT[v] + 1 + d)
            ans = min(ans, dS[v] + dT[u] + 1 + d)
    else:
        # No cycle containing S and T; use a branching vertex
        for v in range(N):
            if len(adj[v]) >= 3:
                if v != S and v != T and dS[v] + dT[v] == d:
                    cost = 2 * (dS[v] + dT[v]) + 2
                else:
                    cost = 2 * (dS[v] + dT[v]) + 4
                ans = min(ans, cost)

    if ans == INF:
        print(-1)
    else:
        print(ans)

