    solve()

import sys

def make_primes(limit):
    sieve = bytearray(b'\x01') * (limit + 1)
    sieve[0:2] = b'\x00\x00'
    for i in range(2, int(limit ** 0.5) + 1):
        if sieve[i]:
            start = i * i
            step = i
            sieve[start:limit + 1:step] = b'\x00' * (((limit - start) // step) + 1)
    return [i for i in range(limit + 1) if sieve[i]]

PRIMES = make_primes(31623)

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    T = int(data[0])
    out = []
    idx = 1
    for _ in range(T):
        N = int(data[idx])
        idx += 1

        if N == 1:
            out.append("20250126 1")
            continue

        temp = N
        factors = []

        for p in PRIMES:
            if p * p > temp:
                break
            if temp % p == 0:
                e = 0
                while temp % p == 0:
                    temp //= p
                    e += 1
                factors.append((p, e))

        if temp > 1:
            factors.append((temp, 1))

        A = 0
        M = 1

        for p, e in factors:
            if p == 2:
                if e == 1:
                    m = 4
                else:
                    m = 1 << (e + 2)
                a = 3
            else:
                m = p ** (e + 1)
                a = p + 1

            inv = pow(M % m, -1, m)
            t = ((a - A) % m) * inv % m
            A = A + M * t
            M = M * m
            A %= M

        out.append(f"{A} {M}")

    sys.stdout.write("\n".join(out))

