def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    it = iter(data)
    N = next(it)
    X = next(it)

    groups = [[] for _ in range(3)]
    total = [0, 0, 0]

    for _ in range(N):
        v = next(it) - 1
        a = next(it)
        c = next(it)
        groups[v].append((a, c))
        total[v] += a

    dps = []

    for v in range(3):
        dp = [-1] * (X + 1)
        dp[0] = 0

        for a, c in groups[v]:
            for cost in range(X, c - 1, -1):
                prev = dp[cost - c]
                if prev >= 0:
                    val = prev + a
                    if val > dp[cost]:
                        dp[cost] = val

        best = dp[0]
        for cost in range(1, X + 1):
            if dp[cost] < best:
                dp[cost] = best
            else:
                best = dp[cost]

        dps.append(dp)

    def can(k):
        total_cost = 0
        for dp in dps:
            idx = bisect_left(dp, k)
            if idx > X:
                return False
            total_cost += idx
            if total_cost > X:
                return False
        return True

    low = 0
    high = min(total) + 1

    while high - low > 1:
        mid = (low + high) // 2
        if can(mid):
            low = mid
        else:
            high = mid

    print(low)

