MOD = 998244353

def calc_F(c2, M, fact, weight, inv, pow10):
    if M == 0:
        return 1

    cs = []
    As = []
    for e in range(1, 10):
        if c2[e] > 0:
            cs.append(c2[e])
            As.append(pow10[e])

    L = len(cs)
    B = [1] * L
    F = fact[M]  # weight[0] * p_0

    for k in range(1, M + 1):
        s = 0
        for i in range(L):
            s += cs[i] * As[i] % MOD * B[i]
        p = (s % MOD) * inv[k] % MOD
        F = (F + p * weight[k]) % MOD

        for i in range(L):
            B[i] = (p - As[i] * B[i]) % MOD

    return F


