    sum_val = [0] * 10

    for i in range(1, N + 1):
        d = len(str(i))
        counts[d] += 1
        sum_val[d] = (sum_val[d] + i) % MOD

    M = N - 1

    fact = [1] * (M + 1)
    for i in range(1, M + 1):
        fact[i] = fact[i - 1] * i % MOD

    inv = [0] * (M + 1)
    if M >= 1:
        inv[1] = 1
        for i in range(2, M + 1):
            inv[i] = MOD - (MOD // i) * inv[MOD % i] % MOD

    weight = [0] * (M + 1)
    for k in range(M + 1):
        weight[k] = fact[k] * fact[M - k] % MOD

    pow10 = [1] * 10
    for e in range(1, 10):
        pow10[e] = pow10[e - 1] * 10 % MOD

    ans = 0

    for d in range(1, 10):
        if counts[d] == 0:
            continue

        c2 = counts[:]
        c2[d] -= 1

        F = calc_F(c2, M, fact, weight, inv, pow10)
        ans = (ans + sum_val[d] * F) % MOD

    print(ans)


