class Solution:
    def distanceSum(self, m: int, n: int, k: int) -> int:
        MOD = 10**9 + 7
        N = m * n

        def row_sum(length: int) -> int:
            if length < 2:
                return 0
            return (length * (length - 1) * (length + 1) // 6) % MOD

        total_dist = (
            (n * n) % MOD * row_sum(m) +
            (m * m) % MOD * row_sum(n)
        ) % MOD

        a = N - 2
        b = k - 2

        if b < 0 or b > a:
            return 0

        fact = [1] * (a + 1)
        for i in range(1, a + 1):
            fact[i] = fact[i - 1] * i % MOD

        inv_fact = [1] * (a + 1)
        inv_fact[a] = pow(fact[a], MOD - 2, MOD)
        for i in range(a, 0, -1):
            inv_fact[i - 1] = inv_fact[i] * i % MOD

        ways = fact[a] * inv_fact[b] % MOD * inv_fact[a - b] % MOD

        return total_dist * ways % MOD

