        left = d[k << 1]
        right = d[(k << 1) | 1]
        d[k] = left if left >= right else right

    def find_first_ge(val, d=d, lz=lz, size=size):
        k = 1
        while k < size:
            z = lz[k]
            if z:
                lc = k << 1
                d[lc] += z
                if lc < size:
                    lz[lc] += z
                rc = lc | 1
                d[rc] += z
                if rc < size:
                    lz[rc] += z
                lz[k] = 0
            if d[k << 1] >= val:
                k = k << 1
            else:
                k = (k << 1) | 1
        return k - size + 1

    def find_first_gt(val, d=d, lz=lz, size=size):
        k = 1
        while k < size:
            z = lz[k]
            if z:
                lc = k << 1
                d[lc] += z
                if lc < size:
                    lz[lc] += z
                rc = lc | 1
                d[rc] += z
                if rc < size:
                    lz[rc] += z
                lz[k] = 0
            if d[k << 1] > val:
                k = k << 1
            else:
                k = (k << 1) | 1
        return k - size + 1

    def range_add(l, r, f, d=d, lz=lz, size=size, log=log):
        l += size
        r += size
        l0, r0 = l, r

        for i in range(log, 0, -1):
            if ((l0 >> i) << i) != l0:
                k = l0 >> i
                z = lz[k]
                if z:
                    lc = k << 1
                    d[lc] += z
                    if lc < size:
                        lz[lc] += z
                    rc = lc | 1
                    d[rc] += z
                    if rc < size:
                        lz[rc] += z
                    lz[k] = 0
            if ((r0 >> i) << i) != r0:
                k = (r0 - 1) >> i
                z = lz[k]
                if z:
                    lc = k << 1
                    d[lc] += z
                    if lc < size:
                        lz[lc] += z
                    rc = lc | 1
                    d[rc] += z
                    if rc < size:
                        lz[rc] += z
                    lz[k] = 0

        while l < r:
            if l & 1:
                d[l] += f
                if l < size:
                    lz[l] += f
                l += 1
            if r & 1:
                r -= 1
                d[r] += f
                if r < size:
                    lz[r] += f
            l >>= 1
            r >>= 1

        l, r = l0, r0
        for i in range(1, log + 1):
            if ((l >> i) << i) != l:
                k = l >> i
                left = d[k << 1]
                right = d[(k << 1) | 1]
                d[k] = left if left >= right else right
            if ((r >> i) << i) != r:
                k = (r - 1) >> i
                left = d[k << 1]
                right = d[(k << 1) | 1]
                d[k] = left if left >= right else right

    for _ in range(N):
        L = data[idx]
