import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it))
    p = int(next(it))
    A = []
    for _ in range(N):
        row = [int(next(it)) for _ in range(N)]
        A.append(row)

    # p = 2: every zero becomes 1, and every non-zero is already 1.
    # So B is the all-ones matrix. B^2 = N * J, so each entry is N mod 2.
    if p == 2:
        ans = N % 2
        line = ' '.join([str(ans)] * N)
        sys.stdout.write('\n'.join([line] * N))
        return

    # Build C: fixed entries, zeros set to 0.
    C = [[0] * N for _ in range(N)]
    K = 0
    for i in range(N):
        for j in range(N):
            if A[i][j] == 0:
                K += 1
            else:
                C[i][j] = A[i][j] % p

    def mat_mul(A, B, mod):
        n = len(A)
        C = [[0] * n for _ in range(n)]
        for i in range(n):
            Ai = A[i]
            Ci = C[i]
            for k in range(n):
                aik = Ai[k]
                if aik:
                    Bk = B[k]
                    for j in range(n):
                        Ci[j] += aik * Bk[j]
            for j in range(n):
                Ci[j] %= mod
        return C

    def mat_pow(mat, exp, mod):
        n = len(mat)
        res = [[0] * n for _ in range(n)]
        for i in range(n):
            res[i][i] = 1 % mod
        base = mat
        while exp > 0:
            if exp & 1:
                res = mat_mul(res, base, mod)
            exp >>= 1
            if exp:
                base = mat_mul(base, base, mod)
        return res

    Cp = mat_pow(C, p, p)

    # T collects paths where exactly one zero entry appears p-1 times
    # and one fixed entry appears once.
    T = [[0] * N for _ in range(N)]
    if p == 3:
        for u in range(N):
            for v in range(N):
                if A[u][v] == 0:
                    if u == v:
                        # self-loop: fixed edge at beginning or at end
                        for a in range(N):
                            T[a][u] = (T[a][u] + C[a][u]) % p
                        for b in range(N):
                            T[u][b] = (T[u][b] + C[u][b]) % p
                    else:
                        # e=(u,v) twice, fixed edge (v,u) in the middle
                        T[u][v] = (T[u][v] + C[v][u]) % p
    else:  # p > 3
        for u in range(N):
            if A[u][u] == 0:
                # only self-loop zero entries can be repeated p-1 times
                for a in range(N):
                    T[a][u] = (T[a][u] + C[a][u]) % p
                for b in range(N):
                    T[u][b] = (T[u][b] + C[u][b]) % p

    # For every zero variable, the sum over x in F_p^* is p-1 ≡ -1.
    sign = pow(p - 1, K, p)

    ans = [[0] * N for _ in range(N)]
    for i in range(N):
        for j in range(N):
            ans[i][j] = (sign * (Cp[i][j] + T[i][j])) % p

    out_lines = []
    for i in range(N):
        out_lines.append(' '.join(map(str, ans[i])))
    sys.stdout.write('\n'.join(out_lines))

