        if (N - 1) % A != 0:
            print("No")
            return
        for L, R in intervals:
            lower = (L - 1 + A - 1) // A
            upper = (R - 1) // A
            if lower <= upper:
                print("No")
                return
        print("Yes")
        return

    # A < B
    full = (1 << B) - 1
    win = ((1 << (B - A + 1)) - 1) << (A - 1)
    mask = 1

    # Constants are safe because max tail-start delay is <= 342
    TH = 500
    P = 30

    def proc_good(mask, length):
        if length <= 0:
            return mask
        if length <= TH:
            for _ in range(length):
                if mask & win:
                    mask = ((mask << 1) | 1) & full
                else:
                    mask = (mask << 1) & full
            return mask
        else:
            any_reach = False
            for _ in range(P):
                if mask & win:
                    mask = ((mask << 1) | 1) & full
                    any_reach = True
                else:
                    mask = (mask << 1) & full
            if any_reach:
                return full
            else:
                return 0

    def proc_bad(mask, length):
        if length >= B:
            return 0
        return (mask << length) & full

    if M == 0:
        mask = proc_good(mask, N - 1)
    else:
        L1, R1 = intervals[0]
        mask = proc_good(mask, L1 - 2)
        mask = proc_bad(mask, R1 - L1 + 1)

        for i in range(1, M):
            _, R_prev = intervals[i - 1]
            L_cur, R_cur = intervals[i]
            gap = L_cur - R_prev - 1
            mask = proc_good(mask, gap)
            mask = proc_bad(mask, R_cur - L_cur + 1)

        _, R_last = intervals[-1]
        mask = proc_good(mask, N - R_last)

    print("Yes" if (mask & 1) else "No")


