from typing import List
from bisect import bisect_left

class Solution:
    def maximumWeight(self, intervals: List[List[int]]) -> List[int]:
        n = len(intervals)
        arr = []
        for i, (l, r, w) in enumerate(intervals):
            arr.append((r, l, w, i))
        arr.sort()
        ends = [r for r, l, w, i in arr]

        # dp[k][i] = best (score, sorted_index_tuple) using at most k intervals
        # among the first i intervals after sorting by right endpoint.
        dp = [[(0, ())] * (n + 1) for _ in range(5)]

        for i in range(n):
            r, l, w, idx = arr[i]
            prev_count = bisect_left(ends, l)  # intervals ending strictly before l

            for k in range(1, 5):
                skip_score, skip_tuple = dp[k][i]

                prev_score, prev_tuple = dp[k - 1][prev_count]
                take_score = prev_score + w
                cand_tuple = tuple(sorted(prev_tuple + (idx,)))

                if take_score > skip_score or (
                    take_score == skip_score and cand_tuple < skip_tuple
                ):
                    dp[k][i + 1] = (take_score, cand_tuple)
                else:
                    dp[k][i + 1] = (skip_score, skip_tuple)

        return list(dp[4][n][1])

