class Solution:
    def minLength(self, s: str, numOps: int) -> int:
        n = len(s)

        def can(k: int) -> bool:
            INF = 10**9
            dp0 = [INF] * (k + 1)
            dp1 = [INF] * (k + 1)

            if s[0] == '0':
                dp0[1] = 0
                dp1[1] = 1
            else:
                dp0[1] = 1
                dp1[1] = 0

            for i in range(1, n):
                ndp0 = [INF] * (k + 1)
                ndp1 = [INF] * (k + 1)

                cost0 = 0 if s[i] == '0' else 1
                cost1 = 1 - cost0
                limit = min(k, i)

                for r in range(1, limit + 1):
                    v = dp0[r]
                    if v < INF:
                        if r < k:
                            ndp0[r + 1] = min(ndp0[r + 1], v + cost0)
                        ndp1[1] = min(ndp1[1], v + cost1)

                    v = dp1[r]
                    if v < INF:
                        if r < k:
                            ndp1[r + 1] = min(ndp1[r + 1], v + cost1)
                        ndp0[1] = min(ndp0[1], v + cost0)

                dp0, dp1 = ndp0, ndp1

            return min(min(dp0), min(dp1)) <= numOps

        lo, hi = 1, n
        while lo < hi:
            mid = (lo + hi) // 2
            if can(mid):
                hi = mid
            else:
                lo = mid + 1

        return lo

import sys

def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return

    it = iter(data)
    N = int(next(it))
    M = int(next(it))
    sx = int(next(it))
    sy = int(next(it))

    houses_by_y = {}
    houses_by_x = {}

    for i in range(N):
        x = int(next(it))
        y = int(next(it))
        houses_by_y.setdefault(y, []).append((x, i))
        houses_by_x.setdefault(x, []).append((y, i))

    intervals_by_y = {}
    intervals_by_x = {}

    cx, cy = sx, sy

    for _ in range(M):
        d = next(it)
        c = int(next(it))

        if d == b'U':
            ny = cy + c
            intervals_by_x.setdefault(cx, []).append((cy, ny))
            cy = ny
        elif d == b'D':
            ny = cy - c
            intervals_by_x.setdefault(cx, []).append((ny, cy))
            cy = ny
        elif d == b'L':
            nx = cx - c
            intervals_by_y.setdefault(cy, []).append((nx, cx))
            cx = nx
        else:  # b'R'
            nx = cx + c
            intervals_by_y.setdefault(cy, []).append((cx, nx))
            cx = nx

    covered = [False] * N

    # Houses covered by horizontal moves
    for y, items in houses_by_y.items():
        intervals = intervals_by_y.get(y)
        if not intervals:
            continue

        intervals.sort(key=lambda p: p[0])
        merged = []
        for l, r in intervals:
            if not merged or l > merged[-1][1]:
                merged.append([l, r])
            else:
                if r > merged[-1][1]:
                    merged[-1][1] = r

        items.sort(key=lambda p: p[0])
        j = 0
        mlen = len(merged)

        for x, idx in items:
            while j < mlen and merged[j][1] < x:
                j += 1
            if j < mlen and merged[j][0] <= x <= merged[j][1]:
                covered[idx] = True

    # Houses covered by vertical moves
    for x, items in houses_by_x.items():
        intervals = intervals_by_x.get(x)
        if not intervals:
            continue

        intervals.sort(key=lambda p: p[0])
        merged = []
        for l, r in intervals:
            if not merged or l > merged[-1][1]:
                merged.append([l, r])
            else:
                if r > merged[-1][1]:
                    merged[-1][1] = r

        items.sort(key=lambda p: p[0])
        j = 0
        mlen = len(merged)

        for y, idx in items:
            while j < mlen and merged[j][1] < y:
                j += 1
            if j < mlen and merged[j][0] <= y <= merged[j][1]:
                covered[idx] = True

    ans = sum(covered)
    sys.stdout.write(f"{cx} {cy} {ans}\n")


