def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    N = data[0]
    A = data[1:1 + N]

    max_sum = max(A) * 2
    ans = 0

    # k = v2(A_i + A_j)
    for k in range(max_sum.bit_length()):
        T = 1 << k
        mask = (T << 1) - 1  # modulo 2^(k+1)

        cnt = {}
        sm = {}

        for a in A:
            r = a & mask
            cnt[r] = cnt.get(r, 0) + 1
            sm[r] = sm.get(r, 0) + a

        for r, c in cnt.items():
            s = (T - r) & mask

            if r < s:
                c2 = cnt.get(s)
                if c2 is not None:
                    ans += (sm[r] * c2 + c * sm[s]) // T
            elif r == s:
                ans += ((c + 1) * sm[r]) // T

    print(ans)

