import sys

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    N = int(data[0])
    A = list(map(int, data[1:1 + N]))

    left = [-1] * N
    right = [-1] * N
    parent = [-1] * N
    stack = []

    # Build Cartesian tree with leftmost maximum as root.
    for i in range(N):
        last = -1
        ai = A[i]
        while stack and A[stack[-1]] < ai:
            last = stack.pop()
        if last != -1:
            left[i] = last
            parent[last] = i
        if stack:
            right[stack[-1]] = i
            parent[i] = stack[-1]
        stack.append(i)

    root = parent.index(-1)

    # Post-order traversal to compute subtree sums.
    order = []
    st = [root]
    while st:
        v = st.pop()
        order.append(v)
        if left[v] != -1:
            st.append(left[v])
        if right[v] != -1:
            st.append(right[v])

    S = A[:]
    for v in reversed(order):
        if left[v] != -1:
            S[v] += S[left[v]]
        if right[v] != -1:
            S[v] += S[right[v]]

    # Determine whether starting at v can absorb its entire subtree.
    self_promote = [False] * N
    for v in range(N):
        if left[v] != -1:
            self_promote[v] = True
        elif right[v] == -1:
            self_promote[v] = True
        else:
            self_promote[v] = (A[v + 1] < A[v])

    # f[v] = highest ancestor reachable from v if we already have sum S[v].
    f = [0] * N
    f[root] = root
    st = [root]
    while st:
        p = st.pop()
        lc = left[p]
        if lc != -1:
            if S[lc] > A[p]:
                f[lc] = f[p]
            else:
                f[lc] = lc
            st.append(lc)
        rc = right[p]
        if rc != -1:
            if S[rc] > A[p]:
                f[rc] = f[p]
            else:
                f[rc] = rc
            st.append(rc)

    ans = [0] * N
    for v in range(N):
        if self_promote[v]:
            ans[v] = S[f[v]]
        else:
            ans[v] = A[v]

    sys.stdout.write(' '.join(map(str, ans)))

if __name__ == "__main__":
    solve()

from typing import List

class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        T = threshold
        present = [False] * (T + 1)
        isolated = 0

        for x in nums:
            if x > T:
                isolated += 1
            else:
                present[x] = True

        parent = list(range(T + 1))

        def find(x: int) -> int:
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        first = [-1] * (T + 1)

        for d in range(1, T + 1):
            if not present[d]:
                continue
            for m in range(d, T + 1, d):
                f = first[m]
                if f == -1:
                    first[m] = d
                else:
                    rf = find(f)
                    rd = find(d)
                    if rf != rd:
                        parent[rd] = rf

        components = 0
        for d in range(1, T + 1):
            if present[d] and find(d) == d:
                components += 1

        return components + isolated
